-- Saves an ERD Explorer data model, "Water utility star schema", with the star schema
-- annotations for the water_star tables (Lakebase source). Generated by generate_star.py.
-- Open ERD Explorer once first so it creates its refdata tables, then run:
--   psql "host=<lakebase-host> dbname=databricks_postgres user=<you> sslmode=require" -f load_model_lakebase.sql
-- In the app: Lakebase, schema water_star, Data model: Water utility star schema.
DO $$ BEGIN
  IF to_regclass('refdata.data_model') IS NULL THEN
    RAISE EXCEPTION 'refdata.data_model does not exist yet: open ERD Explorer once, then run this again';
  END IF;
END $$;
DELETE FROM refdata.data_model WHERE source_system = 'lakebase' AND scope = 'water_star' AND lower(name) = 'water utility star schema';
WITH m AS (
  INSERT INTO refdata.data_model (name, description, source_system, scope, content, created_by, updated_by)
  VALUES ('Water utility star schema', 'Facts and dimensions of the sample water utility warehouse',
          'lakebase', 'water_star', '{"tables": [], "positions": {}, "relationships": [], "cardinality": {}, "star": {"water_star.dim_date": {"role": "dimension", "scd": 1, "surrogate": "date_sk", "business": ["full_date"], "grain": null, "identity": false}, "water_star.dim_customer": {"role": "dimension", "scd": 2, "surrogate": "customer_sk", "business": ["customer_id"], "grain": null, "identity": true}, "water_star.dim_meter": {"role": "dimension", "scd": 1, "surrogate": "meter_sk", "business": ["meter_no"], "grain": null, "identity": true}, "water_star.dim_tariff": {"role": "dimension", "scd": 1, "surrogate": "tariff_sk", "business": ["tariff_code"], "grain": null, "identity": true}, "water_star.dim_site": {"role": "dimension", "scd": 1, "surrogate": "site_sk", "business": ["site_code"], "grain": null, "identity": true}, "water_star.dim_asset": {"role": "dimension", "scd": 1, "surrogate": "asset_sk", "business": ["asset_tag"], "grain": null, "identity": true}, "water_star.dim_work_type": {"role": "dimension", "scd": 1, "surrogate": "work_type_sk", "business": ["work_type_code"], "grain": null, "identity": true}, "water_star.dim_wq_parameter": {"role": "dimension", "scd": 1, "surrogate": "parameter_sk", "business": ["parameter_code"], "grain": null, "identity": true}, "water_star.fact_meter_read": {"role": "fact", "scd": null, "surrogate": null, "business": [], "grain": "One row per meter read (a customer''s quarterly reading of one meter)", "identity": true}, "water_star.fact_work_order": {"role": "fact", "scd": null, "surrogate": null, "business": [], "grain": "One row per completed work order", "identity": true}, "water_star.fact_water_quality": {"role": "fact", "scd": null, "surrogate": null, "business": [], "grain": "One row per lab result (one parameter of one sample)", "identity": true}}}'::jsonb, 'sample-data', 'sample-data')
  RETURNING *
)
INSERT INTO refdata.data_model_version (model_id, version, name, description, content, saved_by)
SELECT id, version, name, description, content, 'sample-data' FROM m;
